const helpers = this.helpers;

const TICK = 0.05;
const floorTick = x => Math.round(Math.floor(x / TICK + 1e-9) * TICK * 100) / 100;
const ceilTick = x => Math.round(Math.ceil(x / TICK - 1e-9) * TICK * 100) / 100;
const r2 = x => Math.round(x * 100) / 100;
const esc = s => String(s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const inr = n => '₹' + Number(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const inr0 = n => '₹' + Number(n).toLocaleString('en-IN', { maximumFractionDigits: 0 });
const mean = a => a.reduce((x, y) => x + y, 0) / a.length;
const short = sym => sym.replace(/\.(NS|BO)$/, '');

// Time in India (works wherever the n8n server runs)
const nowIst = new Date(Date.now() + 19800e3);
const today = nowIst.toISOString().slice(0, 10);
const timeStr = nowIst.toISOString().slice(11, 16);
