const frac = Math.min(1, Math.max(0, (mins - 555) / 375));
const istDate = t => new Date((t + 19800) * 1000).toISOString().slice(0, 10);
const dShort = t => new Date((t + 19800) * 1000).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', timeZone: 'UTC' });

// ---------- chart study ----------
function analyze(res, symbol, name) {
  const qt = res.indicators.quote[0];
  const rows = [];
  res.timestamp.forEach((t, k) => {
    const o = qt.open[k], h = qt.high[k], l = qt.low[k], c = qt.close[k], v = qt.volume ? qt.volume[k] : 0;
    if ([o, h, l, c].every(x => x !== null && x !== undefined)) rows.push({ t, o, h, l, c, v: v || 0 });
  });
  if (rows.length < 60) throw new Error('not enough price history');
  const n = rows.length, last = rows[n - 1], prev = rows[n - 2];
  const live = inSession && istDate(last.t) === today;
  const closes = rows.map(r => r.c);
  const price = last.c;

  const a = 1 / 14;
  let atr = null, g = null, ls = null;
  rows.forEach((r, k) => {
    const pc = k ? rows[k - 1].c : null;
    const tr = pc === null ? r.h - r.l : Math.max(r.h - r.l, Math.abs(r.h - pc), Math.abs(r.l - pc));
    atr = atr === null ? tr : (1 - a) * atr + a * tr;
    if (k) {
      const d = r.c - pc, gain = Math.max(d, 0), loss = Math.max(-d, 0);
      g = g === null ? gain : (1 - a) * g + a * gain;
      ls = ls === null ? loss : (1 - a) * ls + a * loss;
    }
  });
  const rsi = ls === 0 ? 100 : 100 - 100 / (1 + g / ls);

  const smaAt = (k, len) => k + 1 >= len ? mean(closes.slice(k + 1 - len, k + 1)) : null;
  const sma20 = smaAt(n - 1, 20), sma50 = smaAt(n - 1, 50);
  const prior20 = rows.slice(n - 21, n - 1);
  const high20 = Math.max(...prior20.map(r => r.h));
  const avgVol = mean(prior20.map(r => r.v));
  let volRatio = null;
  if (avgVol > 0) volRatio = live ? (frac >= 0.25 ? last.v / (avgVol * frac) : null) : last.v / avgVol;
  const uptrend = sma20 > sma50 && price > sma50;
  const trend = uptrend && price > sma20 ? 'up' : (sma20 < sma50 && price < sma50 ? 'down' : 'sideways');
  const low3 = Math.min(...rows.slice(-3).map(r => r.l));

  const breakout = [price > high20, price - high20 <= atr, price > sma50, volRatio === null ? null : volRatio >= 1.2, rsi >= 50 && rsi < 80];
  const pullback = [uptrend, low3 <= sma20 * 1.005, price >= sma20, rsi >= 40 && rsi <= 65, price > prev.c];
  const fires = c => c.every(x => x !== false);
  const signals = [];
  if (fires(breakout)) signals.push('Breakout');
  if (fires(pullback)) signals.push('Pullback bounce');

  const smaSeries = len => rows.map((r, k) => { const v = smaAt(k, len); return v === null ? null : r2(v); });
  return {
    symbol, name, company: res.meta.longName || res.meta.shortName || name, live, last, price, atr, rsi, sma20, sma50,
    high20, volRatio, trend, signals,
    chart: { rows: rows.slice(-70), sma20: smaSeries(20).slice(-70), sma50: smaSeries(50).slice(-70) },
  };
}

// Stop-loss, target and size if you buy at `entry`
function planAt(entry, atr, qty) {
  let stop = floorTick(entry - S.atrMult * atr);
  if (!(stop < entry)) stop = floorTick(entry - 1.5 * atr);
  if (!(stop < entry)) stop = floorTick(entry * 0.97);
  const risk = entry - stop;
  const target = floorTick(entry + S.rr * risk);
  const p = { entry: r2(entry), stop, target, risk: r2(risk), lossPct: r2(risk / entry * 100), gainPct: r2((target - entry) / entry * 100) };
  let q = qty || null;
  if (!q && S.capital > 0) {
    q = Math.floor((S.capital * S.riskPct / 100) / risk);
    q = Math.min(q, Math.floor(S.capital / entry));
  }
  if (q) { p.qty = q; p.cost = r2(q * entry); p.maxLoss = r2(q * risk); p.maxGain = r2(q * (target - entry)); }
  return p;
}

// Should you buy? Plain answer plus the price to use for the plan.
function decide(A) {
  if (A.signals.length) return { verdict: 'buy', entry: A.price, label: 'Your plan if you buy now at ' + inr(A.price),
    line: '✅ <b>Yes, it looks like a good time to buy</b> (around ' + inr(A.price) + ').' };
  if (A.trend === 'down') return { verdict: 'avoid', entry: A.price, label: 'If you still decide to buy at ' + inr(A.price),
    line: '🛑 <b>No, this is not a good time to buy.</b> The price has been falling. It is safer to stay away for now.' };
  if (A.price > A.high20) { const e = ceilTick(A.sma20);
    return { verdict: 'wait', entry: e, label: 'Your plan if you buy at ' + inr(e),
      line: '⏳ <b>Wait, do not rush.</b> The price has already jumped (or few people are buying). A safer buy point is a small dip near <b>' + inr(e) + '</b>.' }; }
  const e = ceilTick(A.high20 + TICK);
  return { verdict: 'wait', entry: e, label: 'Your plan if you buy at ' + inr(e),
    line: '⏳ <b>Not yet.</b> Buy only if the price goes above <b>' + inr(e) + '</b> (its recent high). That would show buyers are getting strong.' };
}

function why(A) {
  const L = [];
  L.push(A.trend === 'up' ? 'The stock has been going up lately.' : A.trend === 'down' ? 'The stock has been going down lately.' : 'The stock is moving sideways, with no clear direction.');
