    : 'The price is still below its highest point of the last 20 days (' + inr(A.high20) + ').');
  if (A.volRatio === null) L.push('It is too early in the day to judge how many people are trading it.');
  else if (A.volRatio >= 1.2) L.push('More people than usual are trading it (strong interest).');
  else L.push('Trading is normal or low, so there is not much new interest yet.');
  L.push(A.rsi >= 80 ? 'It has risen very fast and may be too hot, so a fall-back is possible.'
    : A.rsi >= 50 ? 'Buying strength looks healthy.' : A.rsi >= 40 ? 'Buying strength is average.' : 'Buying strength is weak.');
  if (A.signals.includes('Pullback bounce')) L.push('It dipped to its 20-day average price and is bouncing back up, a common good buy point.');
