// ---------- profit alert for a stock you hold (Zerodha) ----------
function composeProfit(A, h) {
  const gain = x => (x >= 0 ? '+' : '') + x.toFixed(1) + '%';
  let verdict, protect;
  if (A) {
    protect = floorTick(Math.max(h.avg, h.last - 2 * A.atr));
    const weak = A.trend === 'down' || A.price < A.sma20, hot = A.rsi >= 75, strong = A.trend === 'up' && A.price >= A.sma20 && !hot;
    if (weak) verdict = '🔴 <b>Consider selling at least half now.</b> The chart is getting weaker, so this profit could shrink.';
    else if (hot) verdict = '🟠 <b>Consider booking part of the profit (about half).</b> The price rose very fast and may cool off or fall back for a while. You can keep the rest.';
    else if (strong) verdict = '🟢 <b>You can hold.</b> The chart is still strong. Protect your profit with the stop-loss below, and sell if the price falls to it.';
    else verdict = '🟡 <b>Mixed signs.</b> Booking part of the profit is reasonable. Keep a stop-loss for the rest.';
  } else {
    protect = floorTick(Math.max(h.avg, h.last * 0.95));
    verdict = '🟡 <b>I could not read the chart for this stock</b>, so I cannot say if it is still strong. Booking part of the profit is a safe choice. Keep a stop-loss for the rest.';
  }
  const protectPct = (protect - h.avg) / h.avg * 100;
  const L = [];
  L.push('🎉 <b>Profit alert: ' + esc(h.sym) + ' is up ' + h.pct.toFixed(1) + '%</b>');
  L.push('Your average buy price: ' + inr(h.avg) + '\nPrice now: <b>' + inr(h.last) + '</b>\nYou hold ' + h.qty + ' shares, so your profit is about <b>' + inr0(h.profit) + '</b> (before tax and charges).');
  L.push('<b>Should you sell?</b>\n' + verdict);
  if (A) {
    const w = [];
    w.push(A.trend === 'up' ? 'The stock has been going up lately.' : A.trend === 'down' ? 'The stock has been going down lately.' : 'The stock is moving sideways.');
    w.push(A.price >= A.sma20 ? 'The price is above its 20-day average, which shows short-term strength.' : 'The price is below its 20-day average, which shows short-term weakness.');
    w.push(A.rsi >= 75 ? 'It has risen very fast and may be too hot.' : A.rsi >= 50 ? 'Buying strength looks healthy.' : 'Buying strength has become weak.');
    L.push('<b>What the chart says</b>\n' + w.map(x => '• ' + esc(x)).join('\n'));
  }
  L.push('🛡 <b>Protect your profit</b>\nPlace a stop-loss at <b>' + inr(protect) + '</b>. If the price falls to it and you sell, you still keep ' + (protectPct > 0.2 ? 'about ' + gain(protectPct) : 'your money (about break-even)') + '.');
  L.push('I will tell you again if the profit reaches ' + (h.milestone + h.step) + '%, or if it falls below ' + h.lowLine + '%.\n\n<i>Profits are taxed, and selling within one year of buying is taxed at a higher rate. This is chart study, not financial advice. The decision is yours.</i>');
  return L.join('\n\n');
}

// ---------- main ----------
const out = [];
const say = (j, text) => out.push({ json: { chatId: j.chatId, text } });
const pick = (a, b) => [a, b].filter(Boolean).join('\n\n');

for (const it of $input.all()) {
  const j = it.json;
  if (!j.symbol && !(j.candidates && j.candidates.length)) { if (j.text) say(j, j.text); continue; }
  const mode = j.mode || 'details';
  const quiet = mode === 'monitor' || mode === 'position' || mode === 'profit';
  const ack = j.ack ? '💬 ' + esc(j.ack) : '';

  const loaded = await load(j);
  let A = null;
  if (loaded) { try { A = analyze(loaded.res, loaded.sym, j.name); } catch (e) { A = null; } }
  if (!A && mode === 'profit') { say(j, composeProfit(null, j.h)); continue; }   // still tell the user, using Zerodha's numbers
  if (!A) {
    if (!quiet) say(j, '❌ I could not get price data for <b>' + esc(j.name || j.symbol) + '</b>. Please check the name, or send its NSE symbol (like TCS), and try again.');
    continue;
  }

  if (mode === 'details') {
    const d = decide(A), p = planAt(d.entry, A.atr);
    let prefix = '';
    if (j.addToWatch) {
      if (sd.watchlist.some(w => w.symbol === A.symbol)) prefix = '👀 It is already on your watchlist.';
      else { sd.watchlist.push({ name: A.company, symbol: A.symbol }); prefix = '👀 I added it to your watchlist. I will message you when it looks good to buy.'; }
    }
    const url = await chartLink(A, p);
    const text = pick(ack, pick(prefix, [
      header(A) + closedNote(A), '<b>Should you buy?</b>\n' + d.line, planBlock(d.label, p),
      '<b>Why I say this</b>\n' + why(A),
      url ? '📈 <a href="' + url + '">See the chart with your buy, stop-loss and target</a>' : '',
      '👉 After you buy, tell me, for example: "I bought ' + esc(short(A.symbol)) + ' at ' + Math.round(p.entry) + '". I will then watch your exit for you.',
    ].filter(Boolean).join('\n\n'))) + FOOT;
    say(j, text);
  }

  else if (mode === 'bought') {
    const buy = j.buyPrice || A.price;
    const p = planAt(buy, A.atr, j.qty);
    const pos = { symbol: A.symbol, name: A.company, buyPrice: r2(buy), qty: j.qty || null, stop: p.stop, target: p.target, risk: p.risk, date: today, alerts: {}, breakeven: false };
    const had = sd.positions.some(x => x.symbol === A.symbol);
    sd.positions = sd.positions.filter(x => x.symbol !== A.symbol).concat([pos]);
    const lines = [
      '✅ <b>Noted! You bought ' + esc(A.company) + '</b> at <b>' + inr(buy) + '</b>' + (j.qty ? ' (' + j.qty + ' shares)' : '') + '.' + (had ? ' (I updated my earlier note.)' : ''),
      j.buyPrice ? '' : 'ℹ️ You did not tell me your buy price, so I used today\'s price. If it was different, tell me, for example: "I bought ' + esc(short(A.symbol)) + ' at 520".',
      '<b>Your exit plan</b>',
      '🛑 Stop-loss: <b>' + inr(p.stop) + '</b> — sell if the price falls to this (you lose about ' + p.lossPct + '%' + (j.qty ? ', around ' + inr0(j.qty * p.risk) : '') + ')',
      '🎯 Target: <b>' + inr(p.target) + '</b> — sell here to book profit (you gain about ' + p.gainPct + '%' + (j.qty ? ', around ' + inr0(j.qty * (p.target - buy)) : '') + ')',
      'I will message you when the price reaches either level. If the price moves up well, I will also move your stop-loss up to protect your money.',
      'After you sell, tell me "I sold ' + esc(short(A.symbol)) + '".',
    ].filter(Boolean).join('\n');
    say(j, pick(ack, lines) + FOOT);
  }

  else if (mode === 'status') {
    const pos = sd.positions.find(x => x.symbol === A.symbol);
    if (!pos) continue;
    const pnl = (A.price - pos.buyPrice) / pos.buyPrice * 100;
    const toStop = A.price - pos.stop, toTarget = pos.target - A.price, total = pos.target - pos.stop;
    let verdict;
    if (A.price <= pos.stop) verdict = '🔴 The price is at or below your stop-loss. Selling now limits your loss.';
    else if (A.price >= pos.target) verdict = '🎯 The price reached your target. You can book your profit.';
    else if (toTarget / total <= 0.2) verdict = '🟢 Very close to your target. Be ready to book profit.';
    else if (toStop / total <= 0.2) verdict = '🟠 Close to your stop-loss. Keep a careful eye.';
    else verdict = '⏸ Hold. The price is between your stop-loss and your target.';
    const money = pos.qty ? ' (' + (pnl >= 0 ? 'profit' : 'loss') + ' about ' + inr0(Math.abs(A.price - pos.buyPrice) * pos.qty) + ')' : '';
    const lines = [
      '📌 <b>' + esc(A.company) + '</b> — you bought at ' + inr(pos.buyPrice),
      'Now: <b>' + inr(A.price) + '</b> (' + marketNote(A) + ')',
      (pnl >= 0 ? '🟢 Up ' : '🔴 Down ') + Math.abs(r2(pnl)) + '% since you bought' + money,
      '🛑 Stop-loss: ' + inr(pos.stop) + '   🎯 Target: ' + inr(pos.target),
      verdict,
    ].join('\n');
    say(j, pick(ack, lines));
  }

  else if (mode === 'profit') {
    say(j, composeProfit(A, j.h));
  }

  else if (mode === 'monitor') {
    if (!A.live || !A.signals.length) continue;
    const fresh = A.signals.filter(s => sd.lastAlerts[A.symbol + '|' + s] !== today);
    if (!fresh.length) continue;
    fresh.forEach(s => { sd.lastAlerts[A.symbol + '|' + s] = today; });
    A.signals = fresh;
    const d = decide(A), p = planAt(d.entry, A.atr);
    const url = await chartLink(A, p);
    say(j, [
      '🟢 <b>Buy alert: ' + esc(A.company) + '</b> (buy and hold)',
      'This stock looks good to buy now, around <b>' + inr(A.price) + '</b> (live, ' + timeStr + ').',
      planBlock(d.label, p), '<b>Why I say this</b>\n' + why(A),
      url ? '📈 <a href="' + url + '">See the chart</a>' : '',
      sd.kiteAccessToken
        ? '\ud83d\udc49 If you buy it in Zerodha, I will see it in your holdings and tell you when the profit goes above ' + (sd.profitAlertPct || 10) + '% so you can decide whether to sell.'
        : '👉 If you buy, tell me: "I bought ' + esc(short(A.symbol)) + ' at ' + Math.round(p.entry) + '" and I will watch your exit.',
    ].filter(Boolean).join('\n\n') + FOOT);
  }

  else if (mode === 'position') {
    const pos = sd.positions.find(x => x.symbol === A.symbol);
    if (!pos || !A.live) continue;
    pos.alerts = pos.alerts || {};
    const price = A.price, pnl = r2((price - pos.buyPrice) / pos.buyPrice * 100);
    const money = pos.qty ? ' (about ' + inr0(Math.abs(price - pos.buyPrice) * pos.qty) + ')' : '';
    const sellNote = '\nAfter you sell, tell me "I sold ' + esc(short(A.symbol)) + '" so I stop these alerts.';
    if (price <= pos.stop && pos.alerts.stop !== today) {
      pos.alerts.stop = today;
      say(j, '🔴 <b>SELL ALERT: ' + esc(A.company) + '</b>\nThe price fell to your stop-loss (' + inr(pos.stop) + '). Now: <b>' + inr(price) + '</b>.\nYou bought at ' + inr(pos.buyPrice) + ', so you are ' + (pnl >= 0 ? 'up ' : 'down ') + Math.abs(pnl) + '%' + money + '.\n<b>Selling now limits your loss.</b>' + sellNote);
    } else if (price >= pos.target && pos.alerts.target !== today) {
      pos.alerts.target = today;
      say(j, '🎯 <b>SELL ALERT: ' + esc(A.company) + '</b>\nThe price reached your target (' + inr(pos.target) + '). Now: <b>' + inr(price) + '</b>.\nYou bought at ' + inr(pos.buyPrice) + ', so you are up ' + pnl + '%' + money + '.\n<b>This is a good time to book your profit.</b>' + sellNote);
    } else if (!pos.breakeven && pos.stop < pos.buyPrice && price >= pos.buyPrice + pos.risk) {
      pos.breakeven = true; pos.stop = r2(pos.buyPrice);
      say(j, 'ℹ️ <b>' + esc(A.company) + ' is doing well</b> (up ' + pnl + '%).\nI moved your stop-loss up to your buy price, <b>' + inr(pos.stop) + '</b>. Now you cannot lose money on this trade unless the price falls back below it.\nYour target is still ' + inr(pos.target) + '.');
    }
  }
}
Object.keys(sd.lastAlerts).forEach(k => { if (sd.lastAlerts[k] !== today) delete sd.lastAlerts[k]; });
return out;
